export type EmptyArtName = keyof typeof ART;

export function EmptyArt({ name, className }: { name: EmptyArtName; className?: string }): ReactNode {
  return <span aria-hidden className={cn("mx-auto block w-full max-w-[220px] [&>svg]:h-auto [&>svg]:w-full", className)} dangerouslySetInnerHTML={{ __html: ART[name] }} />;
}

/** An empty screen: the illustration, what is missing, one line on why, and the one thing to do. */
export function EmptyScreen({
  art,
  title,
  body,
  action,
  className,
}: {
  art: EmptyArtName;
  title: string;
  body: ReactNode;
  action?: ReactNode;
  className?: string;
}): ReactNode {
  return (
    <div className={cn("mx-auto flex w-full max-w-md flex-col items-center px-4 py-12 text-center", className)}>
      <EmptyArt name={art} />
      <h2 className="mt-6 text-base font-semibold tracking-tight text-ink">{title}</h2>
      <div className="mt-1.5 text-sm leading-relaxed text-ink-soft">{body}</div>
      {action ? <div className="mt-5">{action}</div> : null}
    </div>
  );
}
